def even_odd_palindrome(n):
    def is_palindrome(num):
        """Check if a number is a palindrome."""
        return str(num) == str(num)[::-1]
    
    evens = 0
    odds = 0
    
    for i in range(1, n + 1):
        if is_palindrome(i):
            if i % 2 == 0:
                evens += 1
            else:
                odds += 1
    
    return (evens, odds)

# Test the function with provided examples
