def histogram(test):
    """Given a string representing a space separated lowercase letters, return a dictionary
    of the letter with the most repetition and containing the corresponding count.
    If several letters have the same occurrence, return all of them.
    
    Example:
    histogram('a b c') == {'a': 1, 'b': 1, 'c': 1}
    histogram('a b b a') == {'a': 2, 'b': 2}
    histogram('a b c a b') == {'a': 2, 'b': 2}
    histogram('b b b b a') == {'b': 4}
    histogram('') == {}
    """
    if not test:
        return {}

    # Split the input string into a list of characters
    chars = test.split()
    char_count = {}

    # Count occurrences of each character
    for char in chars:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Find the maximum occurrence count
    max_occurrence = max(char_count.values(), default=0)

    # Filter the dictionary to only include characters that occur max_occurrence times
    result = {char: count for char, count in char_count.items() if count == max_occurrence}

    return result

